SELECT CASE WHEN rating >= 4.6 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating, COUNT(*) AS cnt, SUM(SUM(rating)) OVER (ORDER BY CASE WHEN rating >= 4.6 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END) AS cumulative_rating FROM suppliers WHERE rating BETWEEN 3.9 AND 4.0 GROUP BY CASE WHEN rating >= 4.6 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END;
